var LINES={
  '幽默':['你是我今天遇到的 bug，一直在我脑子里跑。','我的 IQ 不高，但对你是一见钟情。','你是我的专属变量，值永远唯一。'],
  '文艺':['遇见你，是所有温柔的开始。','想把你的名字写进每一封未寄出的信。','你是人间四月天，也是我心动的原点。'],
  '土味':['你是我的优乐美，我就可以把你捧在手心。','近朱者赤，近你者甜。','我怀疑你是碳酸饮料，不然怎么让我一直冒泡。'],
  '英文':['Are you French? Because Eiffel for you.','Do you have a map? I keep getting lost in your eyes.','Is your name Google? Because you have everything I am searching for.']
};
function pickupLine(category, rng){
  rng=rng||Math.random;
  if(!LINES[category]) category='幽默';
  var bank=LINES[category];
  return {line:bank[Math.floor(rng()*bank.length)], category:category};
}
var EXPORTS={pickupLine:pickupLine};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PickupLineForgePure = EXPORTS; }
